import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * output_length;
    if (idx >= total_elements) return;

    int b = idx / (out_channels * output_length);
    int oc = (idx % (out_channels * output_length)) / output_length;
    int op = idx % output_length;

    float output_val = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int ip_plus_padding = op + padding - k * dilation;
        if (ip_plus_padding < 0) continue;
        if (ip_plus_padding % stride != 0) continue;
        int ip = ip_plus_padding / stride;
        if (ip >= input_length) continue;

        for (int ic = 0; ic < in_channels; ++ic) {
            int input_idx = b * in_channels * input_length + ic * input_length + ip;
            int weight_idx = ic * out_channels * kernel_size + oc * kernel_size + k;
            output_val += input[input_idx] * weight[weight_idx];
        }
    }

    if (has_bias) {
        output_val += bias[oc];
    }

    output[idx] = output_val;
}

torch::Tensor conv_transpose1d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int stride,
    int padding,
    int dilation,
    int output_length
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_length_ = input.size(2);
    auto out_channels = weight.size(1);
    auto kernel_size = weight.size(2);

    auto output = torch::zeros({batch_size, out_channels, output_length}, input.options());

    int total_elements = batch_size * out_channels * output_length;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose1d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.has_value() ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_length_,
        output_length,
        kernel_size,
        stride,
        padding,
        dilation,
        bias.has_value()
    );

    return output;
}
"""

conv_transpose_cpp_source = """
torch::Tensor conv_transpose1d_cuda(
    torch::Tensor input, 
    torch::Tensor weight, 
    torch::optional<torch::Tensor> bias,
    int stride, 
    int padding, 
    int dilation,
    int output_length
);
"""

conv_transpose = load_inline(
    name='conv_transpose1d',
    cpp_sources=conv_transpose_cpp_source,
    cuda_sources=conv_transpose_source,
    functions=['conv_transpose1d_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self.weight = nn.Parameter(torch.empty(in_channels, out_channels, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output_length = (x.size(2) - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + 1
        return conv_transpose.conv_transpose1d_cuda(
            x,
            self.weight,
            self.bias,
            self.stride,
            self.padding,
            self.dilation,
            output_length
        )
